package com.fitforge.ai;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fitforge.cardio.CardioAiQuota;
import com.fitforge.cardio.CardioRepository;
import com.fitforge.common.ApiResponse;
import com.fitforge.nutrition.*;
import com.fitforge.progress.WeightRepository;
import com.fitforge.workout.WorkoutSetRepository;
import com.fitforge.workout.WorkoutSessionRepository;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;
import java.time.LocalDate;
import java.util.*;

@RestController @RequestMapping("/api/ai")
public class AiNutritionController {
 private final GeminiService gemini;private final AiLiveContextService context;private final NutritionModuleService nutrition;private final WeightRepository weights;private final WorkoutSetRepository sets;private final WorkoutSessionRepository workoutSessions;private final CardioRepository cardio;private final ObjectMapper mapper;private final CardioAiQuota quota;
 public AiNutritionController(GeminiService gemini,AiLiveContextService context,NutritionModuleService nutrition,WeightRepository weights,WorkoutSetRepository sets,WorkoutSessionRepository workoutSessions,CardioRepository cardio,ObjectMapper mapper,CardioAiQuota quota){this.gemini=gemini;this.context=context;this.nutrition=nutrition;this.weights=weights;this.sets=sets;this.workoutSessions=workoutSessions;this.cardio=cardio;this.mapper=mapper;this.quota=quota;}

 /** Raw camera upload from the Diet tab: multipart image -> validated -> Gemini vision analysis. */
 @PostMapping("/meal-scan/upload") public ApiResponse<AiDtos.MealAnalysis> mealUpload(Authentication a,@RequestParam("image") org.springframework.web.multipart.MultipartFile image,@RequestParam(required=false) String prompt){
  String email=a.getName();quota.enforce(email);
  if(image==null||image.isEmpty())throw new IllegalArgumentException("Image is required");
  if(image.getSize()>8_000_000L)throw new IllegalArgumentException("Image too large (max 8 MB)");
  String mime=image.getContentType()==null?"image/jpeg":image.getContentType();
  if(!mime.toLowerCase(Locale.ROOT).startsWith("image/"))throw new IllegalArgumentException("Only image uploads are supported");
  byte[] bytes;
  try{bytes=image.getBytes();}catch(Exception e){throw new IllegalArgumentException("Could not read the image");}
  try{
   String base64=Base64.getEncoder().encodeToString(bytes);
   return ApiResponse.ok("Meal analyzed",gemini.scan(new AiDtos.MealScanRequest(base64,mime,prompt),context.load(email)));
  }finally{Arrays.fill(bytes,(byte)0);}
 }

 @PostMapping("/protein-coach") public ApiResponse<AiDtos.ProteinCoach> protein(Authentication a,@RequestParam(required=false) LocalDate date){String email=a.getName();quota.enforce(email);LocalDate day=date==null?LocalDate.now():date;var stats=nutrition.proteinData(email,day);String task="For an Indian beginner, write one short supportive Hinglish note explaining how to use these three exact protein options. Do not change quantities or macros. Remaining target="+stats.remaining()+"g; exact options="+stats.options();String note=gemini.nutritionText(email,task,context.load(email));return ApiResponse.ok("Protein options generated",new AiDtos.ProteinCoach(stats.target(),stats.consumed(),stats.remaining(),stats.options(),note));}

 @PostMapping("/diet-adjuster") public ApiResponse<AiDtos.DietAdjuster> adjust(Authentication a){String email=a.getName();quota.enforce(email);LocalDate end=LocalDate.now(),start=end.minusDays(6);var logs=nutrition.recentDiary(email,start,end);var weight=weights.findByUserEmailAndDateBetweenOrderByDateAsc(email,start,end);var cardioLogs=cardio.findByUserEmailOrderBySessionDateDesc(email);var recentSets=sets.findByUserEmailOrderByWorkoutDateDesc(email,org.springframework.data.domain.PageRequest.of(0,12));double avgC=logs.stream().mapToDouble(NutritionModuleDtos.Diary::calories).sum()/7.0,avgP=logs.stream().mapToDouble(NutritionModuleDtos.Diary::proteinG).sum()/7.0,avgFiber=logs.stream().mapToDouble(NutritionModuleDtos.Diary::fiberG).sum()/7.0;var live=context.load(email);double currentWeight=weight.isEmpty()?live.protocolWeightKg():weight.get(weight.size()-1).getWeightKg();String facts="Review this 7-day nutrition/training history. Missing diary days are unlogged, never zero intake. 7-day macro/fiber averages: "+Math.round(avgC)+" kcal, "+Math.round(avgP)+"g protein, "+Math.round(avgFiber)+"g fiber. Weight: "+weight.stream().map(w->w.getDate()+":"+w.getWeightKg()+"kg").toList()+". Cardio: "+cardioLogs.stream().limit(7).map(c->c.getActivity()+" "+c.getDistanceKm()+"km, "+c.getDurationMinutes()+"min at "+c.getPaceMinPerKm()+"min/km").toList()+". Strength: "+recentSets.stream().limit(8).map(s->s.getExerciseName()+" "+s.getWeightKg()+"kg x"+s.getReps()).toList()+". Give a short, non-extreme Hinglish summary without aggressive calorie cuts.";String note=gemini.nutritionText(email,facts,live);List<AiDtos.DietAdjustment> suggestions=List.of(adjustment("Protein consistency","Use logged 7-day average; unlogged days are unknown.","Add one measured curd, egg, paneer, chicken, soy, dal, or whey serving only if target is short; review after a week."),adjustment("Fiber and vegetables","Tracking suggests a gradual fiber/vegetable habit may help.","Add a bowl of vegetables or fruit with dal/beans daily; increase gradually and hydrate."),adjustment("Steady calorie budget","Scale and food estimates fluctuate day to day.","Keep the current budget steady for 2 weeks; change it only from a consistent weight trend and recovery."));return ApiResponse.ok("Diet adjustments generated",new AiDtos.DietAdjuster(currentWeight,avgC,avgP,avgFiber,suggestions,note));}

 @PostMapping("/grocery-generate") public ApiResponse<AiDtos.GroceryPlan> groceries(Authentication a,@RequestParam(required=false) LocalDate weekStartDate){String email=a.getName();quota.enforce(email);var live=context.load(email);String task="Create a practical 7-day Indian grocery list. Return only JSON {categories:[{category,items:[{name,quantity,unit,purchased:false}]}]}. Use categories Protein, Vegetables, Fruits, Dairy, Grains, Nuts & Seeds. Match protein target "+nutrition.proteinTarget(email)+"g and calorie budget "+nutrition.dailyCalorieBudget(email)+" kcal.";String answer=gemini.nutritionJson(email,task,live);String json;try{json=answer.substring(answer.indexOf('{'),answer.lastIndexOf('}')+1);if(!mapper.readTree(json).has("categories"))throw new IllegalArgumentException("No categories");}catch(Exception ex){json=fallbackGroceryJson();}var saved=nutrition.putGrocery(email,new NutritionModuleDtos.GroceryInput(weekStartDate==null?LocalDate.now():weekStartDate,json));return ApiResponse.ok("7-day grocery list generated",new AiDtos.GroceryPlan(saved,"Generated for your calorie and protein targets. Review household quantities before shopping."));}

 @PostMapping("/activity-suggestion") public ApiResponse<AiDtos.ActivitySuggestion> activity(Authentication a,@RequestBody AiDtos.ActivityRequest input){String email=a.getName();quota.enforce(email);LocalDate date=input.date()==null?LocalDate.now():input.date();String recovery=input.recoveryStatus().trim().toUpperCase(Locale.ROOT),activity=input.dailyActivityLevel().trim().toUpperCase(Locale.ROOT);if(!Set.of("POOR","OK","GOOD").contains(recovery)||!Set.of("LOW","NORMAL","HIGH").contains(activity))throw new IllegalArgumentException("recoveryStatus must be POOR, OK, or GOOD and dailyActivityLevel must be LOW, NORMAL, or HIGH");var food=nutrition.day(email,date);var water=nutrition.hydration(email,date);var workoutsToday=workoutSessions.findByUserEmailAndSessionDateBetweenOrderBySessionDateDesc(email,date.atStartOfDay(),date.plusDays(1).atStartOfDay());int kcal;String suggestion,reason;double budget=nutrition.dailyCalorieBudget(email);if(recovery.equals("POOR")||food.calories()<budget*.65||water.waterMl()<water.waterGoalMl()*.5||!workoutsToday.isEmpty()){kcal=0;suggestion="Rest or normal daily movement only";reason="Recovery, low intake/hydration, or today's workout takes priority.";}else if(recovery.equals("GOOD")&&activity.equals("LOW")&&food.calories()>=budget*.85&&water.waterMl()>=water.waterGoalMl()*.7){kcal=100;suggestion="Optional easy walk or light cycling, about 15-25 minutes";reason="Recovery and intake look adequate and daily movement is low.";}else{kcal=50;suggestion="Optional easy walk, about 10-15 minutes";reason="A small comfortable walk may fit; skip it if tired.";}var live=context.load(email);String note=gemini.nutritionText(email,"In one short Hinglish sentence, explain the optional "+kcal+" kcal activity: "+suggestion+". It never changes the usual workout, never reduces pendingGapKcal, and can be skipped. Recovery="+recovery+", activity="+activity+".",live);return ApiResponse.ok("Optional activity suggestion generated",new AiDtos.ActivitySuggestion(kcal,suggestion,true,true,reason+" No calorie backlog is exercise debt.",note));}

 @GetMapping("/daily-verdict/{date}") public ApiResponse<AiDtos.DailyVerdict> verdict(Authentication a,@PathVariable LocalDate date){String email=a.getName();quota.enforce(email);var d=nutrition.day(email,date);var h=nutrition.hydration(email,date);double proteinTarget=nutrition.proteinTarget(email),budget=nutrition.dailyCalorieBudget(email);String task="Write a supportive Hinglish end-of-day nutrition verdict in 2-3 sentences and exactly one actionable tip for tomorrow. No shame or extreme restriction. Today's logged intake: "+d.calories()+" kcal / "+budget+" kcal budget, protein "+d.proteinG()+"g / "+proteinTarget+"g, fiber "+d.fiberG()+"g / "+h.fiberTargetG()+"g, water "+h.waterMl()+"ml / "+h.waterGoalMl()+"ml. Missing tracking is not failure.";String note=gemini.nutritionText(email,task,context.load(email));return ApiResponse.ok("Daily nutrition verdict generated",new AiDtos.DailyVerdict(date,d.calories(),budget,d.proteinG(),proteinTarget,d.fiberG(),h.fiberTargetG(),h.waterMl(),h.waterGoalMl(),note,extractTip(note)));}

 private AiDtos.DietAdjustment adjustment(String title,String rationale,String action){return new AiDtos.DietAdjustment(UUID.randomUUID().toString(),UUID.randomUUID().toString(),UUID.randomUUID().toString(),title,rationale,action,false);}
 private String extractTip(String text){for(String line:text.split("\\R")){String s=line.trim();if(s.toLowerCase(Locale.ROOT).startsWith("tomorrow tip:")||s.toLowerCase(Locale.ROOT).startsWith("tip:"))return s.substring(s.indexOf(':')+1).trim();}return text;}
 private String fallbackGroceryJson(){return "{\"categories\":[{\"category\":\"Protein\",\"items\":[{\"name\":\"Eggs\",\"quantity\":12,\"unit\":\"pieces\",\"purchased\":false},{\"name\":\"Chicken breast or soy chunks\",\"quantity\":700,\"unit\":\"g\",\"purchased\":false}]},{\"category\":\"Vegetables\",\"items\":[{\"name\":\"Seasonal vegetables\",\"quantity\":2,\"unit\":\"kg\",\"purchased\":false}]},{\"category\":\"Fruits\",\"items\":[{\"name\":\"Bananas and seasonal fruit\",\"quantity\":14,\"unit\":\"pieces\",\"purchased\":false}]},{\"category\":\"Dairy\",\"items\":[{\"name\":\"Curd or milk\",\"quantity\":2,\"unit\":\"kg or L\",\"purchased\":false}]},{\"category\":\"Grains\",\"items\":[{\"name\":\"Atta, rice, oats\",\"quantity\":2,\"unit\":\"kg combined\",\"purchased\":false}]},{\"category\":\"Nuts & Seeds\",\"items\":[{\"name\":\"Almonds or peanuts\",\"quantity\":200,\"unit\":\"g\",\"purchased\":false}]}]}";}
}
